    {
      "type": "share",
      "to": ["REG"],
      "inject_refs": ["S3-I1"],
      "statement": "Share OpCo's fraud wave alert with REG so the telecom regulator can assess whether SIM-replacement authentication controls are adequate and take any necessary regulatory action."
    },
