      "type": "insufficient_evidence",
      "statement": "The available excerpts do not state whether any bank customers have been affected by the refused SIM replacements or whether any actual fraud has occurred.",
      "inject_refs": ["S3-I1"],
      "evidence": []
    }
  ]
}

{
  "situation": "I know FIN reports that fraud model v2 went live for SIM-replacement requests at 08:00 and the fraud dashboard shows refused SIM replacements up about tenfold, labelled a 'fraud wave'. I do not know whether the refusals are appropriate fraud blocks or are blocking legitimate subscribers, nor whether OpCo tested the model before deployment.",
  "claims": [
    {
      "type": "action",
      "verb": "open_incident",
      "params": {
        "topic": "Fraud model v2 live for SIM-replacement requests: refused SIM replacements up tenfold"
      },
      "inject_refs": ["S3-I1"],
      "rationale": {
        "observation": "FIN reports that fraud model v2 went live for SIM-replacement requests at 08:00 and the fraud dashboard shows refused SIM replacements up about tenfold, labelled a 'fraud wave'.",
        "rule": "TDRA is responsible for overseeing the telecommunications sector and Licensees.",
        "inference": "A sudden tenfold increase in refused SIM replacements is a significant event requiring a regulatory incident record."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TEL-LAW#0017",
          "quote": "The Authority is responsible for overseeing the telecommunications sector and Licensees in accordance with this Decree-Law and its implementing regulations and the directives issued by the High Committee."
        }
      ]
    },
    {
      "type": "action",
      "verb": "request_report",
      "params": {
        "from": "NOC",
        "topic": "Impact of fraud model v2 on SIM-replacement requests, refusal reasons, false-positive assessment, and measures to protect legitimate subscribers"
      },
      "inject_refs": ["S3-I1"],
      "rationale": {
        "observation": "FIN reports a sharp increase in refused SIM replacements after fraud model v2 went live.",
        "rule": "TDRA may regulate the conditions, level and scope of services and require information from licensees.",
        "inference": "TDRA should require OpCo/NOC to report on the model's impact and whether legitimate requests are being denied."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TDRA-CPR-2#0000",
          "quote": "Article (14)3 of Federal Law by Decree No. 3 of 2003 Regarding the Organisation of the Telecommunications Sector, as amended (hereinafter the “Telecommunications Law”) grants the TDRA the power to issue regulations, instructions, decisions and rules regulating the conditions, level and scope of services provided by the Licensees to subscribers…including the standards and quality of the provided services, terms of supply, the handling of subscriber complaints and disputes, provision of information to subscribers, usage of subscriber personal information and the provision of bills to subscribers."
        }
      ]
    },
    {
      "type": "action",
      "verb": "request_audit",
      "params": {
        "of": "NOC",
        "topic": "Testing, change management, and records for fraud model v2 SIM-replacement deployment"
      },
      "inject_refs": ["S3-I1"],
      "rationale": {
        "observation": "Fraud model v2 was deployed at 08:00 and immediately preceded a tenfold increase in refused SIM replacements.",
        "rule": "TDRA’s oversight includes requiring licensees’ testing and change records.",
        "inference": "An audit of the testing and change records will show whether the model was validated before deployment and why refusals spiked."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TEL-LAW#0017",
          "quote": "The Authority is responsible for overseeing the telecommunications sector and Licensees in accordance with this Decree-Law and its implementing regulations and the directives issued by the High Committee."
        }
      ]
    },
    {
      "type": "action",
      "verb": "issue_direction",
      "params": {
        "to": "NOC",
        "direction": "Immediately assess whether fraud model v2 is blocking legitimate SIM-replacement requests and take corrective measures to avoid unjustified denial of service while maintaining fraud controls."
      },
      "inject_refs": ["S3-I1"],
      "rationale": {
        "observation": "FIN reports refused SIM replacements are up about tenfold.",
        "rule": "TDRA has power to issue instructions and decisions regulating the conditions, level and scope of services.",
        "inference": "TDRA should direct the licensee to correct any over-blocking of legitimate SIM replacements."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TDRA-CPR-2#0000",
          "quote": "Article (14)3 of Federal Law by Decree No. 3 of 2003 Regarding the Organisation of the Telecommunications Sector, as amended (hereinafter the “Telecommunications Law”) grants the TDRA the power to issue regulations, instructions, decisions and rules regulating the conditions, level and scope of services provided by the Licensees to subscribers…including the standards and quality of the provided services, terms of supply, the handling of subscriber complaints and disputes, provision of information to subscribers, usage of subscriber personal information and the provision of bills to subscribers."
        }
      ]
    },
    {
      "type": "gap",
      "gap_type": "no_rule",
      "statement": "UAE telecom consumer protection rules do not explicitly require licensees to balance SIM-replacement fraud controls against legitimate customer access or to test fraud models before deployment.",
      "inject_refs": ["S3-I1"],
      "rationale": {
        "observation": "FIN reports that a fraud model change caused a tenfold increase in refused SIM replacements; the UAE excerpts contain only general consumer protection powers, not specific SIM-swap/replacement fraud-control requirements.",
        "rule": "A regulatory gap exists when an incident reveals a missing specific rule, despite general oversight powers.",
        "inference": "The absence of explicit SIM-replacement fraud-control and legitimate-access balancing rules leaves the handling of such changes to ad hoc regulatory action."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TDRA-CPR-2#0000",
          "quote": "Article (14)3 of Federal Law by Decree No. 3 of 2003 Regarding the Organisation of the Telecommunications Sector, as amended (hereinafter the “Telecommunications Law”) grants the TDRA the power to issue regulations, instructions, decisions and rules regulating the conditions, level and scope of services provided by the Licensees to subscribers…including the standards and quality of the provided services, terms of supply, the handling of subscriber complaints and disputes, provision of information to subscribers, usage of subscriber personal information and the provision of bills to subscribers."
        }
      ],
      "global_examples": [
        {
          "chunk_id": "US-FCC-23-95#0005",
          "quote": "In adopting these rules, we balance the need to protect customers from the harms of SIM swap and port-out fraud with the goal of preserving the relative ease with which customers can obtain legitimate SIM changes and number ports."
        },
        {
          "chunk_id": "US-FCC-23-95#0040",
          "quote": "telecommunications carriers to proactively and regularly review and monitor their policies and procedures to ensure that they continue to be effective at addressing evolving fraud techniques against customer accounts and services-- including SIM swap and port-out fraud--and to conduct analyses of fraud incidents to determine how the fraud occurred and implement measures to prevent such tactics from being successful again in the future."
        }
      ]
    }
  ]
}

{
  "situation": "OpCo’s fraud model v2 went live at 08:00 and refuses roughly ten times as many SIM-replacement requests; several banks now report that customers abroad cannot receive OTPs and are locked out of online banking. I do not yet know whether these refusals are accurate fraud blocks or overblocking, or what authentication criteria OpCo is applying.",
  "claims": [
    {
      "type": "action",
      "verb": "instruct_banks",
      "params": {
        "content": "Licensed banks must ensure customers who cannot receive SMS OTPs, particularly those abroad, can authenticate via mobile banking app or another approved secure channel; do not rely solely on SMS OTP."
      },
      "inject_refs": ["S3-I1", "S3-I2"],
      "rationale": {
        "observation": "OpCo’s fraud model v2 went live at 08:00 and refused SIM-replacement requests increased about tenfold; several banks report customers abroad cannot receive OTPs and are locked out.",
        "rule": "The Central Bank has directed banks and financial institutions to avoid weak OTP channels and adopt more secure authentication such as in-app.",
        "inference": "To protect consumers and prevent unlawful lockouts, CBUAE should instruct banks to provide alternative authentication for customers affected by OpCo’s refusals."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0001",
          "quote": "“This is part of comprehensive guidelines for banks and financial institutions with the subject line of prevention of fraud. The regulator said OTPs should not be shared through weak modes of communication, such as SMS and emails, as they are vulnerable and can be compromised,”"
        },
        {
          "chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0000",
          "quote": "Customers must authenticate transactions using their mobile banking apps for improved security."
        }
      ]
    },
    {
      "type": "share",
      "to": ["NOC"],
      "inject_refs": ["S3-I2"],
      "statement": "Exercise control reports that several banks say customers abroad cannot receive OTPs and are locked out; customers say OpCo refused their SIM replacement requests."
    },
    {
      "type": "gap",
      "gap_type": "conflict",
      "statement": "TDRA’s consumer protection regulation makes OTP the default 2FA method, while CBUAE guidance tells banks not to use SMS OTP because it is weak; no single clear fallback is set for customers abroad who cannot receive SMS OTPs.",
      "inject_refs": ["S3-I2"],
      "rationale": {
        "observation": "Banks report customers abroad cannot receive OTPs and are locked out after OpCo refused SIM replacement requests.",
        "rule": "TDRA default 2FA is OTP; CBUAE says SMS/email OTPs are weak and should not be shared through weak modes.",
        "inference": "Conflicting rules leave no clear operational fallback, causing authentication lockouts for affected customers."
      },
      "evidence": [
        {
          "chunk_id": "UAE-TDRA-CPR-2#0067",
          "quote": "the default method of 2FA shall, in the absence of any approved alternative, be one-time password (OTP)."
        },
        {
          "chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0001",
          "quote": "“This is part of comprehensive guidelines for banks and financial institutions with the subject line of prevention of fraud. The regulator said OTPs should not be shared through weak modes of communication, such as SMS and emails, as they are vulnerable and can be compromised,”"
        }
      ],
      "global_examples": [
        {
          "chunk_id": "US-FCC-23-95#0015",
          "quote": "we decline to enumerate the four specific authentication methods the Commission specified in the SIM Swap and Port-Out Fraud Notice as those that would meet the standard of secure authentication methods."
        }
      ]
    }
  ]
}

{
  "situation": "OpCo's fraud model v2 went live at 08:00 and refused SIM replacements at about ten times the previous rate; after rollback to v1 and enabling the review queue, twin metrics show 100% legitimate pass and no banking lockouts. FIN now reports banks saying customers abroad cannot receive OTPs and are locked out because OpCo refused SIM replacement requests, and I do not know whether production matches the twin or which refusals affected these customers.",
  "claims": [
    {
      "type": "obligation",
      "statement": "OpCo must provide data subjects information about decisions made by automated processing, including profiling, for SIM-replacement refusals affected by the fraud model.",
      "inject_refs": ["S3-I1", "S3-I2"],
      "rationale": {
        "observation": "The fraud model v2 automatically refused SIM replacement requests and FIN reports affected bank customers.",
        "rule": "UAE PDPL Article 13(1)(c) gives data subjects the right to obtain information about decisions made based on automated processing, including profiling.",
        "inference": "OpCo is controller of the subscriber data and must be prepared to provide this information to affected customers."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0047",
          "quote": "c. Decisions made based on automated processing, including profiling."
        }
      ],
      "deadline_hours": null
    },
    {
      "type": "gap",
      "gap_type": "no_rule",
      "statement": "UAE telecom licence has no rule requiring OpCo to notify banks or FIN when its fraud controls cause SIM replacement refusals and lock bank customers out of OTPs.",
      "inject_refs": ["S3-I1", "S3-I2"],
      "rationale": {
        "observation": "FIN reported banks locked out after OpCo refused SIM replacements; the only licence notification duty found is for planned service interruptions.",
        "rule": "UAE-LIC-2-2026#0085 requires advance notice only for planned interruptions to TDRA, interconnecting operators and relevant customers, not financial institutions.",
        "inference": "There is no explicit owner or deadline for notifying banks when fraud controls cause unplanned SIM replacement refusals."
      },
      "evidence": [
        {
          "chunk_id": "UAE-LIC-2-2026#0085",
          "quote": "In the case of a planned interruption of a Telecommunication Service other than a minor interruption, the Licensee shall inform the TDRA, any interconnecting Other Licensed Operators and relevant Customers in advance of such interruption."
        }
      ],
      "global_examples": [
        {
          "chunk_id": "US-FCC-23-95#0004",
          "quote": "requiring that wireless providers notify customers regarding SIM change and port-out requests, offer customers the option to lock their accounts to block processing of SIM changes and number ports, and give advanced notice of available account protection mechanisms."
        }
      ]
    },
    {
      "type": "share",
      "to": ["REG"],
      "inject_refs": ["S3-I2"],
      "statement": "Banks report that customers abroad cannot receive OTPs and are locked out of online banking because OpCo refused SIM replacement requests."
    },
    {
      "type": "insufficient_evidence",
      "statement": "The excerpts do not show whether the specific bank customers abroad who are locked out were refused because of the v2 fraud model or because of an authentication failure, nor do they show current production metrics after rollback.",
      "inject_refs": ["S3-I2"],
      "evidence": []
    }
  ]
}

{
  "situation": "OpCo launched fraud model v2 for SIM-replacement requests at 08:00 and its dashboard shows a tenfold increase in refused SIM replacements; banks report customers abroad are locked out of online banking because OpCo refused their SIM replacement requests. I do not yet have OpCo's own notification to TDRA, classification of the service impact, or restoration plan.",
  "claims": [
    {
      "type": "action",
      "verb": "open_incident",
      "params": {
        "topic": "SIM replacement refusals after fraud model v2 launch and customer OTP lockouts reported by banks"
      },
      "inject_refs": ["S3-I1", "S3-I2"],
      "rationale": {
        "observation": "Banks report customers abroad cannot receive OTPs and are locked out of online banking; customers say OpCo refused their SIM replacement requests.",
        "rule": "The licence requires OpCo to inform TDRA as soon as possible of any unplanned interruption of a Telecommunication Service.",
        "inference": "The reported refusals may constitute an unplanned interruption of SIM replacement service, so TDRA should open a regulatory incident record to assess compliance."
      },
      "evidence": [
        {
          "chunk_id": "UAE-LIC-2-2026#0086",
          "quote": "In the case of any unplanned interruption of a Telecommunication Service, other than minor interruptions, the Licensee shall inform the TDRA, any interconnecting Other Licensed Operators and relevant Customers as soon as possible as to the reason(s) for the interruption as well as the manner and time frames in which the interruption will be resolved."
        }
      ]
    },
    {
      "type": "action",
      "verb": "request_report",
      "params": {
        "from": "NOC",
        "topic": "Provide details on the fraud model v2 change, the number and reasons for refused SIM replacements, impact on customers abroad, and whether TDRA was informed as required"
      },
      "inject_refs": ["S3-I1", "S3-I2"],
      "rationale": {
        "observation": "Fraud model v2 went live at 08:00 and the dashboard shows refused SIM replacements up about tenfold; banks report customers abroad locked out.",
        "rule": "The licence requires the Licensee to inform TDRA of unplanned interruptions and specify reasons and timeframes for resolution.",
        "inference": "TDRA needs information from OpCo to determine whether the refusals are a legitimate fraud response or overbroad and to assess compliance with notification duties."
      },
      "evidence": [
        {
          "chunk_id": "UAE-LIC-2-2026#0086",
          "quote": "In the case of any unplanned interruption of a Telecommunication Service, other than minor interruptions, the Licensee shall inform the TDRA, any interconnecting Other Licensed Operators and relevant Customers as soon as possible as to the reason(s) for the interruption as well as the manner and time frames in which the interruption will be resolved."
        }
      ]
    },
    {
      "type": "obligation",
      "statement": "OpCo must inform TDRA as soon as possible of any unplanned interruption of a Telecommunication Service, including the reason(s) and timeframes for resolution.",
      "inject_refs": ["S3-I2"],
      "rationale": {
        "observation": "Banks report customers abroad are locked out of online banking because OpCo refused SIM replacement requests.",
        "rule": "The licence requires a Licensee to inform TDRA as soon as possible in the case of any unplanned interruption of a Telecommunication Service.",
        "inference": "This duty applies to OpCo now if the refused SIM replacements amount to an unplanned interruption."
      },
      "evidence": [
        {
          "chunk_id": "UAE-LIC-2-2026#0086",
          "quote": "In the case of any unplanned interruption of a Telecommunication Service, other than minor interruptions, the Licensee shall inform the TDRA, any interconnecting Other Licensed Operators and relevant Customers as soon as possible as to the reason(s) for the interruption as well as the manner and time frames in which the interruption will be resolved."
        }
      ],
      "deadline_hours": null
    }
  ]
